import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
from io import BytesIO
import base64
from datetime import datetime

# ── Config ──────────────────────────────────────────────────────────────────
COLOR_PRIMARY = '#1a1a2e'
COLOR_ACCENT = '#e94560'
COLOR_ACCENT2 = '#0f3460'
COLOR_GREEN = '#2ecc71'
COLOR_RED = '#e74c3c'
COLOR_MUTED = '#7f8c8d'
COLOR_BG = '#f8f9fa'
CHART_COLORS = ['#0f3460', '#e94560', '#16213e', '#533483', '#2ecc71', '#e67e22']

plt.rcParams.update({
    'figure.facecolor': 'white',
    'axes.facecolor': 'white',
    'axes.grid': True,
    'grid.alpha': 0.3,
    'grid.color': '#cccccc',
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.labelsize': 12,
    'axes.titlesize': 14,
    'figure.dpi': 150,
    'savefig.bbox': 'tight',
    'savefig.pad_inches': 0.2,
})

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# ── Load data ───────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='mixed')
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['DailyReturn'] = df['Close'].pct_change()
df['CumReturn'] = (1 + df['DailyReturn']).cumprod()
df['DailyRange'] = df['High'] - df['Low']
df['DailyRangePct'] = df['DailyRange'] / df['Close'] * 100
df['RollingVol30'] = df['DailyReturn'].rolling(30).std() * np.sqrt(252) * 100
df['RollingVol90'] = df['DailyReturn'].rolling(90).std() * np.sqrt(252) * 100
df['MA50'] = df['Close'].rolling(50).mean()
df['MA200'] = df['Close'].rolling(200).mean()

# Running max for drawdown
df['RunningMax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['RunningMax']) / df['RunningMax'] * 100

# ── KPIs ────────────────────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
years_span = (last_date - first_date).days / 365.25

cumulative_return = (last_close / first_close - 1) * 100
cagr = ((last_close / first_close) ** (1 / years_span) - 1) * 100
max_drawdown = df['Drawdown'].min()
max_dd_date = df.loc[df['Drawdown'].idxmin(), 'Date']
annualized_vol = df['DailyReturn'].std() * np.sqrt(252) * 100
avg_daily_volume = df['Volume'].mean()

# All-time high / low
ath_idx = df['Close'].idxmax()
ath_price = df.loc[ath_idx, 'Close']
ath_date = df.loc[ath_idx, 'Date']
atl_idx = df['Close'].idxmin()
atl_price = df.loc[atl_idx, 'Close']
atl_date = df.loc[atl_idx, 'Date']

# ── Annual performance ──────────────────────────────────────────────────────
annual = df.groupby('Year').agg(
    Open=('Close', 'first'),
    Close=('Close', 'last'),
    High=('High', 'max'),
    Low=('Low', 'min'),
    AvgVolume=('Volume', 'mean'),
    TotalVolume=('Volume', 'sum'),
    Volatility=('DailyReturn', lambda x: x.std() * np.sqrt(252) * 100),
    TradingDays=('Close', 'count')
).reset_index()
annual['Return'] = (annual['Close'] / annual['Open'] - 1) * 100

# Decade performance
def decade_label(y):
    d = (y // 10) * 10
    return f"{d}s"

annual['Decade'] = annual['Year'].apply(decade_label)
decade_perf = []
for dec, grp in annual.groupby('Decade'):
    start = grp['Open'].iloc[0]
    end = grp['Close'].iloc[-1]
    n_years = len(grp)
    total_ret = (end / start - 1) * 100
    dec_cagr = ((end / start) ** (1 / n_years) - 1) * 100 if n_years > 0 else 0
    decade_perf.append({'Decade': dec, 'StartPrice': start, 'EndPrice': end,
                        'TotalReturn': total_ret, 'CAGR': dec_cagr, 'Years': n_years})
decade_df = pd.DataFrame(decade_perf)

best_year = annual.loc[annual['Return'].idxmax()]
worst_year = annual.loc[annual['Return'].idxmin()]

# ── Major drawdown periods ──────────────────────────────────────────────────
drawdown_periods = []
in_drawdown = False
peak_date = None
trough_date = None
trough_val = 0
threshold = -15

for i, row in df.iterrows():
    if row['Drawdown'] < threshold and not in_drawdown:
        in_drawdown = True
        pk_mask = df.loc[:i, 'Close'] == df.loc[:i, 'RunningMax']
        peak_date = df.loc[pk_mask[pk_mask].index[-1], 'Date']
        trough_val = row['Drawdown']
        trough_date = row['Date']
    elif in_drawdown:
        if row['Drawdown'] < trough_val:
            trough_val = row['Drawdown']
            trough_date = row['Date']
        if row['Drawdown'] > -5:
            in_drawdown = False
            drawdown_periods.append({
                'Peak': peak_date, 'Trough': trough_date,
                'MaxDrawdown': trough_val,
                'Recovery': row['Date']
            })

if in_drawdown:
    drawdown_periods.append({
        'Peak': peak_date, 'Trough': trough_date,
        'MaxDrawdown': trough_val, 'Recovery': None
    })

# ── Volume analysis ─────────────────────────────────────────────────────────
df['VolumeMA50'] = df['Volume'].rolling(50).mean()
volume_spikes = df[df['Volume'] > df['VolumeMA50'] * 3].copy()
volume_spikes = volume_spikes.sort_values('Volume', ascending=False).head(20)

# Era volume comparison
era_bins = [(2000, 2005, '2000–2005'), (2006, 2010, '2006–2010'),
            (2011, 2015, '2011–2015'), (2016, 2020, '2016–2020'), (2021, 2026, '2021–2026')]
era_vols = []
for s, e, label in era_bins:
    mask = (df['Year'] >= s) & (df['Year'] <= e)
    era_vols.append({'Era': label, 'AvgVolume': df.loc[mask, 'Volume'].mean()})
era_vol_df = pd.DataFrame(era_vols)


# ═══════════════════════════════════════════════════════════════════════════════
# CHARTS
# ═══════════════════════════════════════════════════════════════════════════════

# Chart 1: Long-term price trend with MAs
fig, ax = plt.subplots(figsize=(14, 6))
ax.plot(df['Date'], df['Close'], color=COLOR_ACCENT2, linewidth=1.0, label='Close Price', alpha=0.9)
ax.plot(df['Date'], df['MA50'], color=COLOR_ACCENT, linewidth=0.7, label='50-Day MA', alpha=0.7)
ax.plot(df['Date'], df['MA200'], color=COLOR_GREEN, linewidth=0.7, label='200-Day MA', alpha=0.7)
ax.set_ylabel('Price (USD, Split-Adjusted)')
ax.set_title('Nike (NKE) Closing Price — January 2000 to 2026')
ax.legend(loc='upper left', framealpha=0.9)
ax.xaxis.set_major_locator(mdates.YearLocator(2))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
fig.autofmt_xdate()
chart_price_trend = fig_to_base64(fig)

# Chart 2: Log-scale price
fig, ax = plt.subplots(figsize=(14, 5))
ax.semilogy(df['Date'], df['Close'], color=COLOR_ACCENT2, linewidth=1.0)
ax.set_ylabel('Price (USD, Log Scale)')
ax.set_title('NKE Closing Price — Logarithmic Scale')
ax.xaxis.set_major_locator(mdates.YearLocator(2))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:,.0f}'))
fig.autofmt_xdate()
chart_log_price = fig_to_base64(fig)

# Chart 3: Drawdown chart
fig, ax = plt.subplots(figsize=(14, 4))
ax.fill_between(df['Date'], df['Drawdown'], 0, color=COLOR_RED, alpha=0.4)
ax.plot(df['Date'], df['Drawdown'], color=COLOR_RED, linewidth=0.5)
ax.set_ylabel('Drawdown (%)')
ax.set_title('NKE Peak-to-Trough Drawdowns')
ax.xaxis.set_major_locator(mdates.YearLocator(2))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax.set_ylim(min(df['Drawdown'].min() * 1.1, -70), 5)
fig.autofmt_xdate()
chart_drawdown = fig_to_base64(fig)

# Chart 4: Rolling volatility
fig, ax = plt.subplots(figsize=(14, 4))
ax.plot(df['Date'], df['RollingVol30'], color=COLOR_ACCENT, linewidth=0.8, alpha=0.6, label='30-Day Rolling')
ax.plot(df['Date'], df['RollingVol90'], color=COLOR_ACCENT2, linewidth=1.0, label='90-Day Rolling')
ax.set_ylabel('Annualized Volatility (%)')
ax.set_title('NKE Rolling Annualized Volatility')
ax.legend(loc='upper right')
ax.xaxis.set_major_locator(mdates.YearLocator(2))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
fig.autofmt_xdate()
chart_volatility = fig_to_base64(fig)

# Chart 5: Annual returns bar chart
fig, ax = plt.subplots(figsize=(14, 5))
colors_bar = [COLOR_GREEN if r >= 0 else COLOR_RED for r in annual['Return']]
ax.bar(annual['Year'], annual['Return'], color=colors_bar, edgecolor='white', linewidth=0.5)
ax.set_ylabel('Annual Return (%)')
ax.set_title('NKE Year-over-Year Returns')
ax.axhline(y=0, color='black', linewidth=0.5)
ax.set_xticks(annual['Year'][::2])
ax.tick_params(axis='x', rotation=45)
chart_annual_returns = fig_to_base64(fig)

# Chart 6: Volume with price overlay
fig, ax1 = plt.subplots(figsize=(14, 5))
ax1.bar(df['Date'], df['Volume'], color=COLOR_MUTED, alpha=0.4, width=2, label='Daily Volume')
ax1.plot(df['Date'], df['VolumeMA50'], color=COLOR_ACCENT2, linewidth=1.0, label='50-Day Avg Volume')
ax1.set_ylabel('Volume (shares)')
ax1.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x/1e6:.0f}M'))
ax1.set_title('NKE Trading Volume with Price Overlay')
ax1.legend(loc='upper left')
ax2 = ax1.twinx()
ax2.plot(df['Date'], df['Close'], color=COLOR_ACCENT, linewidth=0.8, alpha=0.8, label='Close Price')
ax2.set_ylabel('Price (USD)')
ax2.legend(loc='upper right')
ax1.xaxis.set_major_locator(mdates.YearLocator(2))
ax1.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
fig.autofmt_xdate()
chart_volume = fig_to_base64(fig)

# Chart 7: Daily range (volatility proxy)
fig, ax = plt.subplots(figsize=(14, 4))
daily_range_monthly = df.set_index('Date')['DailyRangePct'].resample('M').mean()
ax.plot(daily_range_monthly.index, daily_range_monthly.values, color=COLOR_ACCENT2, linewidth=1.0)
ax.set_ylabel('Avg Daily Range (% of Close)')
ax.set_title('NKE Monthly Average Daily Price Range')
ax.xaxis.set_major_locator(mdates.YearLocator(2))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
fig.autofmt_xdate()
chart_daily_range = fig_to_base64(fig)

# Chart 8: Cumulative return
fig, ax = plt.subplots(figsize=(14, 5))
ax.plot(df['Date'], (df['CumReturn'] - 1) * 100, color=COLOR_ACCENT2, linewidth=1.2)
ax.fill_between(df['Date'], (df['CumReturn'] - 1) * 100, 0, alpha=0.15, color=COLOR_ACCENT2)
ax.set_ylabel('Cumulative Return (%)')
ax.set_title('NKE Cumulative Return Since January 2000')
ax.xaxis.set_major_locator(mdates.YearLocator(2))
ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:,.0f}%'))
fig.autofmt_xdate()
chart_cumulative = fig_to_base64(fig)

# Chart 9: Volume by era
fig, ax = plt.subplots(figsize=(8, 4))
bars = ax.bar(era_vol_df['Era'], era_vol_df['AvgVolume'], color=CHART_COLORS[:len(era_vol_df)], edgecolor='white')
ax.set_ylabel('Avg Daily Volume')
ax.set_title('Average Daily Trading Volume by Era')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x/1e6:.1f}M'))
for bar, val in zip(bars, era_vol_df['AvgVolume']):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 100000,
            f'{val/1e6:.1f}M', ha='center', va='bottom', fontsize=10)
chart_era_volume = fig_to_base64(fig)


# ═══════════════════════════════════════════════════════════════════════════════
# HTML REPORT
# ═══════════════════════════════════════════════════════════════════════════════

# Build annual performance table rows
annual_table_rows = ""
for _, r in annual.iterrows():
    ret_color = COLOR_GREEN if r['Return'] >= 0 else COLOR_RED
    annual_table_rows += f"""<tr>
        <td>{int(r['Year'])}</td>
        <td>${r['Open']:.2f}</td>
        <td>${r['Close']:.2f}</td>
        <td>${r['High']:.2f}</td>
        <td>${r['Low']:.2f}</td>
        <td style="color:{ret_color}; font-weight:600;">{r['Return']:+.1f}%</td>
        <td>{r['Volatility']:.1f}%</td>
        <td>{r['AvgVolume']/1e6:.1f}M</td>
    </tr>"""

# Build decade table rows
decade_table_rows = ""
for _, r in decade_df.iterrows():
    decade_table_rows += f"""<tr>
        <td>{r['Decade']}</td>
        <td>${r['StartPrice']:.2f}</td>
        <td>${r['EndPrice']:.2f}</td>
        <td style="color:{COLOR_GREEN if r['TotalReturn']>=0 else COLOR_RED}; font-weight:600;">{r['TotalReturn']:+.1f}%</td>
        <td>{r['CAGR']:+.1f}%</td>
    </tr>"""

# Build drawdown table
drawdown_table_rows = ""
for dp in sorted(drawdown_periods, key=lambda x: x['MaxDrawdown']):
    rec_str = dp['Recovery'].strftime('%b %Y') if dp['Recovery'] else 'Not recovered'
    duration = (dp['Trough'] - dp['Peak']).days
    drawdown_table_rows += f"""<tr>
        <td>{dp['Peak'].strftime('%b %Y')}</td>
        <td>{dp['Trough'].strftime('%b %Y')}</td>
        <td style="color:{COLOR_RED}; font-weight:600;">{dp['MaxDrawdown']:.1f}%</td>
        <td>{duration} days</td>
        <td>{rec_str}</td>
    </tr>"""

# Top volume spike table
vol_spike_rows = ""
for _, r in volume_spikes.head(10).iterrows():
    daily_ret = r['DailyReturn'] * 100 if not np.isnan(r['DailyReturn']) else 0
    ret_color = COLOR_GREEN if daily_ret >= 0 else COLOR_RED
    vol_spike_rows += f"""<tr>
        <td>{r['Date'].strftime('%b %d, %Y')}</td>
        <td>{r['Volume']/1e6:.1f}M</td>
        <td>${r['Close']:.2f}</td>
        <td style="color:{ret_color};">{daily_ret:+.1f}%</td>
    </tr>"""

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nike Inc. (NKE) — Historical Stock Performance Analysis (2000–2026)</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

  * {{ margin: 0; padding: 0; box-sizing: border-box; }}

  body {{
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    color: #1a1a2e;
    background: #f0f2f5;
    line-height: 1.65;
  }}

  .report-wrapper {{
    max-width: 1100px;
    margin: 0 auto;
    padding: 40px 20px;
  }}

  /* ── Header ─────────────────────────────────── */
  .report-header {{
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    color: #fff;
    padding: 50px 48px;
    border-radius: 16px;
    margin-bottom: 32px;
    position: relative;
    overflow: hidden;
  }}
  .report-header::before {{
    content: '';
    position: absolute;
    top: -50%;
    right: -20%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(233,69,96,0.15) 0%, transparent 70%);
    border-radius: 50%;
  }}
  .report-header h1 {{
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 8px;
    position: relative;
  }}
  .report-header .subtitle {{
    font-size: 1.05rem;
    opacity: 0.85;
    font-weight: 300;
    position: relative;
  }}
  .report-header .meta {{
    margin-top: 18px;
    font-size: 0.85rem;
    opacity: 0.6;
    position: relative;
  }}

  /* ── KPI Cards ──────────────────────────────── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
  }}
  .kpi-card {{
    background: #fff;
    border-radius: 12px;
    padding: 24px;
    text-align: center;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
    border-top: 3px solid #0f3460;
    transition: transform 0.15s;
  }}
  .kpi-card:hover {{ transform: translateY(-2px); }}
  .kpi-card .kpi-label {{
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: #7f8c8d;
    margin-bottom: 8px;
    font-weight: 600;
  }}
  .kpi-card .kpi-value {{
