import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
from io import BytesIO
import base64
from datetime import datetime

# ── Config ──────────────────────────────────────────────────────────────────
COLOR_PRIMARY = '#1a1a2e'
COLOR_ACCENT = '#e94560'
COLOR_ACCENT2 = '#0f3460'
COLOR_GREEN = '#2ecc71'
COLOR_RED = '#e74c3c'
COLOR_MUTED = '#7f8c8d'
COLOR_BG = '#f8f9fa'
CHART_COLORS = ['#0f3460', '#e94560', '#16213e', '#533483', '#2ecc71', '#e67e22']

plt.rcParams.update({
    'figure.facecolor': 'white',
    'axes.facecolor': 'white',
    'axes.grid': True,
    'grid.alpha': 0.3,
    'grid.color': '#cccccc',
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.labelsize': 12,
    'axes.titlesize': 14,
    'figure.dpi': 150,
    'savefig.bbox': 'tight',
    'savefig.pad_inches': 0.2,
})

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# ── Load data ───────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='mixed')
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['DailyReturn'] = df['Close'].pct_change()
df['CumReturn'] = (1 + df['DailyReturn']).cumprod()
df['DailyRange'] = df['High'] - df['Low']
df['DailyRangePct'] = df['DailyRange'] / df['Close'] * 100
df['RollingVol30'] = df['DailyReturn'].rolling(30).std() * np.sqrt(252) * 100
df['RollingVol90'] = df['DailyReturn'].rolling(90).std() * np.sqrt(252) * 100
df['MA50'] = df['Close'].rolling(50).mean()
df['MA200'] = df['Close'].rolling(200).mean()

# Running max for drawdown
df['RunningMax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['RunningMax']) / df['RunningMax'] * 100

# ── KPIs ────────────────────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
years_span = (last_date - first_date).days / 365.25

cumulative_return = (last_close / first_close - 1) * 100
cagr = ((last_close / first_close) ** (1 / years_span) - 1) * 100
max_drawdown = df['Drawdown'].min()
max_dd_date = df.loc[df['Drawdown'].idxmin(), 'Date']
annualized_vol = df['DailyReturn'].std() * np.sqrt(252) * 100
avg_daily_volume = df['Volume'].mean()

# All-time high / low
ath_idx = df['Close'].idxmax()
ath_price = df.loc[ath_idx, 'Close']
ath_date = df.loc[ath_idx, 'Date']
atl_idx = df['Close'].idxmin()
atl_price = df.loc[atl_idx, 'Close']
atl_date = df.loc[atl_idx, 'Date']

# ── Annual performance ──────────────────────────────────────────────────────
annual = df.groupby('Year').agg(
    Open=('Close', 'first'),
    Close=('Close', 'last'),
    High=('High', 'max'),
    Low=('Low', 'min'),
    AvgVolume=('Volume', 'mean'),
    TotalVolume=('Volume', 'sum'),
    Volatility=('DailyReturn', lambda x: x.std() * np.sqrt(252) * 100),
    TradingDays=('Close', 'count')
).reset_index()
annual['Return'] = (annual['Close'] / annual['Open'] - 1) * 100

# Decade performance
def decade_label(y):
    d = (y // 10) * 10
    return f"{d}s"

annual['Decade'] = annual['Year'].apply(decade_label)
decade_perf = []
for dec, grp in annual.groupby('Decade'):
    start = grp['Open'].iloc[0]
    end = grp['Close'].iloc[-1]
    n_years = len(grp)
    total_ret = (end / start - 1) * 100
    dec_cagr = ((end / start) ** (1 / n_years) - 1) * 100 if n_years > 0 else 0
    decade_perf.append({'Decade': dec, 'StartPrice': start, 'EndPrice': end,
                        'TotalReturn': total_ret, 'CAGR': dec_cagr, 'Years': n_years})
decade_df = pd.DataFrame(decade_perf)

best_year = annual.loc[annual['Return'].idxmax()]
worst_year = annual.loc[annual['Return'].idxmin()]

# ── Major drawdown periods ──────────────────────────────────────────────────
drawdown_periods = []
in_drawdown = False
peak_date = None
trough_date = None
trough_val = 0
threshold = -15

for i, row in df.iterrows():
    if row['Drawdown'] < threshold and not in_drawdown:
        in_drawdown = True
        pk_mask = df.loc[:i, 'Close'] == df.loc[:i, 'RunningMax']
